# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# Estimation with recruitment random effects using wrappers ----
## Setup ----
#' @description Skip the test unless explicitly enabled for heavy integration testing.
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

# Load or prepare any necessary data for testing
if (!file.exists(
  testthat::test_path("fixtures", "parameters_model_comparison_project.RDS")
)) {
  prepare_test_data()
}

load(testthat::test_path("fixtures", "integration_test_data.RData"))

# Set the iteration ID to 1 for accessing specific input/output list
iter_id <- 1

# Extract model input and output data for the specified iteration
om_input <- om_input_list[[iter_id]]
om_output <- om_output_list[[iter_id]]
em_input <- em_input_list[[iter_id]]

fims_data <- FIMS::FIMSFrame(data_big)
n_years <- get_n_years(fims_data)

# Parameters with default settings from the other integration tests, where
# recruitment is estimated through log_devs as random effects
modified_parameters_log_devs <- readRDS(
  testthat::test_path("fixtures", "parameters_model_comparison_project.RDS")
)

# True log recruitment (age-1 numbers) from the operating model
log_recruits_true <- matrix(
  c(t(om_output[["N.age"]])),
  om_input[["nyr"]],
  om_input[["nages"]],
  byrow = TRUE
)[, 1] |>
  log()

# Swap log_devs for log_r. The C++ code fills recruitment in year y (y = 2,
# ..., n_years) with exp(log_r[y - 1]), so log_r has n_years - 1 elements and
# lines up with the log_devs timings (2:n_years). Values are assigned by row
# order in initialize_fims(), so timing is only used as a label here.
modified_parameters_log_r <- modified_parameters_log_devs |>
  dplyr::rows_delete(
    tibble::tibble(
      module_name = "Recruitment",
      label = "log_devs"
    ),
    by = c("module_name", "label")
  ) |>
  dplyr::rows_append(
    tibble::tibble(
      module_name = "Recruitment",
      module_type = "BevertonHolt",
      label = "log_r",
      timing = 2:n_years,
      value = log_recruits_true[2:n_years],
      estimation_type = "random_effects",
      distribution_type = "process",
      distribution = "Dnorm"
    )
  )

## IO correctness ----
test_that("estimation test with recruitment random effects on log_r works", {
  clear()
  fit_log_r <- modified_parameters_log_r |>
    initialize_fims(data = fims_data) |>
    fit_fims(optimize = TRUE)
  clear()

  log_r_estimates <- get_estimates(fit_log_r) |>
    dplyr::filter(module_name == "Recruitment", label == "log_r")

  #' @description Test that log_r has n_years - 1 values that are all estimated as random effects.
  expect_equal(nrow(log_r_estimates), n_years - 1)
  expect_true(all(log_r_estimates[["estimation_type"]] == "random_effects"))
  #' @description Test that the model has n_years - 1 random effects when log_r is estimated as random effects.
  expect_length(get_obj(fit_log_r)[["env"]][["random"]], n_years - 1)
  #' @description Test that the expected recruitment equals exp(log_r) for years 2 to n_years.
  expect_equal(
    get_report(fit_log_r)[["expected_recruitment"]][[1]][2:n_years],
    exp(log_r_estimates[["estimated"]]),
    tolerance = 1e-4
  )
})

test_that("recruitment log_devs and log_r implementations give comparable results", {
  clear()
  fit_log_devs <- modified_parameters_log_devs |>
    initialize_fims(data = fims_data) |>
    fit_fims(optimize = TRUE)
  clear()

  fit_log_r <- modified_parameters_log_r |>
    initialize_fims(data = fims_data) |>
    fit_fims(optimize = TRUE)
  clear()

  #' @description Test that the `nll_components` from the log_r and log_devs fits are approximately equal.
  expect_equal(
    get_report(fit_log_r)[["nll_components"]],
    get_report(fit_log_devs)[["nll_components"]],
    tolerance = 1e-3
  )
  #' @description Test that the `expected_recruitment` from the log_r and log_devs fits are approximately equal.
  expect_equal(
    get_report(fit_log_r)[["expected_recruitment"]],
    get_report(fit_log_devs)[["expected_recruitment"]],
    tolerance = 1e-3
  )
})
